217	            );
218	
219	            log.info("구매자 알림 생성 완료: userId={}, orderId={}", buyer.getId(), order.getId());
220	
221	        } catch (Exception e) {
222	            log.error("주문 완료 처리 실패: orderId={}, error={}", orderId, e.getMessage(), e);
223	            throw new ShipmentException(
224	                    ShipmentErrorCode.ORDER_NOT_FOUND_FOR_SHIPMENT,
225	                    "주문 완료 처리 중 오류 발생: " + e.getMessage(),
226	                    e
227	            );
228	        }
229	    }
