 43	/**
 44	 * 배송 상태 배치 처리를 위한 ItemProcessor
 45	 * 주문 배송 상태를 조회하고 처리합니다.
 46	 */
 47	@Slf4j
 48	public class ShipmentItemProcessor implements ItemProcessor<OrderShipment, OrderShipment> {
 49	
 50	    private final PlaywrightBrowserManager browserManager;
 51	    private final NotificationCommandService notificationService;
 52	    private final OrderShipmentCommandService orderService;
 53	
 54	    private static final String TRACKING_URL_PREFIX = "https://trace.cjlogistics.com/next/tracking.html?wblNo=";
 55	    private static final String STATUS_SELECTOR = "tbody#statusDetail tr";
 56	    private static final int TIMEOUT_MS = 30000; // 30초
 57	
 58	    /**
 59	     * 배송 상태 처리기 생성자
 60	     *
 61	     * @param browserManager Playwright 브라우저 관리자
 62	     * @param notificationService 알림 서비스
 63	     * @param orderService 주문 서비스
 64	     */
 65	    public ShipmentItemProcessor(
 66	            PlaywrightBrowserManager browserManager,
 67	            NotificationCommandService notificationService,
 68	            OrderShipmentCommandService orderService
 69	    ) {
 70	        this.browserManager = browserManager;
 71	        this.notificationService = notificationService;
 72	        this.orderService = orderService;
 73	    }
 74	
 75	    /**
 76	     * 주문 배송의 상태를 외부 서비스를 통해 조회하고 업데이트합니다.
 77	     *
 78	     * @param orderShipment 처리할 배송 정보
 79	     * @return 업데이트된 배송 정보
 80	     * @throws Exception 처리 중 오류 발생 시
 81	     */
 82	    @Override
 83	    public OrderShipment process(OrderShipment orderShipment) throws Exception {
 84	        String trackingNumber = orderShipment.getTrackingNumber();
 85	        Long shipmentId = orderShipment.getId();
 86	
 87	        if (trackingNumber == null || trackingNumber.isBlank()) {
 88	            log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
 89	            throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
 90	        }
 91	
 92	        log.info("배송 상태 처리 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
 93	                shipmentId, trackingNumber, orderShipment.getStatus());
 94	
 95	        Page page = null;
 96	        try {
 97	            // browserManager를 통해 페이지 생성
 98	            page = browserManager.newPage();
 99	            if (page == null) {
100	                throw new ShipmentException(ShipmentErrorCode.BROWSER_INITIALIZATION_ERROR);
101	            }
102	
103	            // 타임아웃 설정
104	            page.setDefaultTimeout(TIMEOUT_MS);
105	
106	            // 배송 추적 URL로 이동
107	            String url = TRACKING_URL_PREFIX + trackingNumber;
108	            log.debug("배송 조회 페이지로 이동: {}", url);
109	            page.navigate(url);
110	
111	            // 배송 상태 테이블 로드 대기
112	            log.debug("배송 상태 테이블 로드 대기");
113	            page.waitForSelector(STATUS_SELECTOR);
114	
115	            // 최종 HTML 가져오기
116	            String renderedHtml = page.content();
117	            log.debug("페이지 HTML 로드 완료 (길이: {})", renderedHtml.length());
118	
119	            // HTML 파싱하여 배송 상태 추출
120	            String statusText = parseStatusFromHtml(renderedHtml, trackingNumber);
121	            ShipmentStatus newStatus = mapToShipmentStatus(statusText);
122	
123	            log.debug("배송 상태 조회 결과: shipmentId={}, statusText={}, mappedStatus={}",
124	                    shipmentId, statusText, newStatus);
125	
126	            // 현재 상태와 동일한 경우 중복 처리 방지
127	            if (orderShipment.getStatus() == newStatus) {
128	                log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
129	                        shipmentId, newStatus);
130	                return orderShipment;
131	            }
132	
133	            // 상태에 따른 처리
134	            if (newStatus == ShipmentStatus.DELIVERED) {
135	                log.info("배송 완료 처리: shipmentId={}, orderId={}",
136	                        shipmentId, orderShipment.getOrder().getId());
137	
138	                // 배송 상태 업데이트
139	                orderShipment.updateStatus(ShipmentStatus.DELIVERED);
140	
141	                // 주문 완료 처리 및 알림
142	                orderService.completeOrder(orderShipment.getOrder().getId());
143	                notificationService.notifyShipmentCompleted(orderShipment.getOrder());
144	
145	            } else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
146	                log.info("배송 출발 처리: shipmentId={}", shipmentId);
147	                orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
148	
149	            } else {
150	                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
151	                orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
152	            }
153	
154	            log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}",
155	                    shipmentId, orderShipment.getStatus());
156	
157	            return orderShipment;
158	
159	        } catch (Exception e) {
160	            log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
161	                    shipmentId, trackingNumber, e.getMessage(), e);
162	
163	            // ShipmentException 타입이 아닌 경우 래핑
164	            if (!(e instanceof ShipmentException)) {
165	                throw new ShipmentException(
166	                        ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
167	                        "배송 상태 조회 중 오류 발생: " + e.getMessage(),
168	                        e
169	                );
170	            }
171	            throw e;
172	        } finally {
173	            // 페이지 리소스 해제
174	            if (page != null) {
175	                try {
176	                    page.close();
177	                    log.debug("페이지 리소스 해제 완료");
178	                } catch (Exception e) {
179	                    log.warn("페이지 닫기 실패: {}", e.getMessage());
180	                }
181	            }
182	        }
183	    }
