31:    private Long id;
33:    @ManyToOne(fetch = FetchType.LAZY)
34:    @JoinColumn(name = "user_id")
35:    private User user; // 주문자
37:    @OneToOne(mappedBy = "order", cascade = CascadeType.ALL, orphanRemoval = true)
38:    private Payment payment; // 연관된 결제 정보
40:    @OneToOne(mappedBy = "order", cascade = CascadeType.ALL, orphanRemoval = true)
41:    private OrderShipment orderShipment; // 구매자 배송 정보
43:    private int totalAmount; // 총 금액
