87:    public void assignOrderShipment(OrderShipment orderShipment) {
88:        this.orderShipment = orderShipment;
89:        if (orderShipment != null && orderShipment.getOrder() != this) {
90:            orderShipment.assignOrder(this);
91:        }
92:    }
